/** "call the CA at 4:30 pm" → {time:'16:30'}; leaves the words as they are */
function otTimeOf(t) {
  const m = String(t).match(/\b(?:at|by|@)?\s*(\d{1,2})(?:[:.](\d{2}))?\s*(a\.?\s?m\.?|p\.?\s?m\.?|baje)\b/i); if (!m) return '';
  let h = +m[1]; const mi = m[2] ? +m[2] : 0, ap = m[3].toLowerCase().replace(/[.\s]/g, '');
  if (ap === 'pm' && h < 12) h += 12; if (ap === 'am' && h === 12) h = 0; if (ap === 'baje' && h < 8) h += 12;
  return h < 24 && mi < 60 ? ('0' + h).slice(-2) + ':' + ('0' + mi).slice(-2) : '';
}
