// ───────────────────────────── owner's private task list (v18.51, owner 17 Nov 2026) ─────────────────────────────
// Only the Owner login can see, add or change these tasks (every call checks the role). Tasks are kept per day; tasks not done
// stay "pending" and are shown on later days until done or moved. Tab "Owner Tasks".
const OT_TAB = 'Owner Tasks', OT_H = ['ID', 'Date', 'Time', 'Task', 'Priority', 'Status', 'Done at', 'Note', 'Created at', 'Moved from'];
function otOwner_(u) { if (!u || u.role !== 'Owner') throw new Error('This task list is only for the owner.'); }
function otObj_(r) {
  return { id: s_(r[0]), date: ymd_(r[1]) || s_(r[1]), time: hoHm_(r[2]), task: s_(r[3]), pri: s_(r[4]) === 'High', status: s_(r[5]) || 'Open',
    doneAt: r[6] ? iso_(r[6]) : '', note: s_(r[7]), at: r[8] ? iso_(r[8]) : '', moved: s_(r[9]) };
}
function otSort_(a, b) { return (a.status === 'Done') - (b.status === 'Done') || (b.pri - a.pri) || ((a.time || '99') < (b.time || '99') ? -1 : (a.time || '99') > (b.time || '99') ? 1 : 0) || (a.at < b.at ? -1 : 1); }
/** d = {date} → that day's tasks, open tasks from earlier days, and counts for today / tomorrow */
function otList_(d, user) {
  otOwner_(user);
  const td = ymd_(new Date()), tm = hoNext_(td), date = /^\d{4}-\d{2}-\d{2}$/.test(d.date || '') ? d.date : td;
  const all = xrows_(OT_TAB, OT_H).map(otObj_).filter(t => t.id);
  return { date: date, today: td, tomorrow: tm, list: all.filter(t => t.date === date).sort(otSort_),
    earlier: all.filter(t => t.status === 'Open' && t.date < td && t.date < date).sort((a, b) => a.date < b.date ? -1 : 1),
    counts: { today: all.filter(t => t.date === td && t.status === 'Open').length, tomorrow: all.filter(t => t.date === tm && t.status === 'Open').length,
      pending: all.filter(t => t.date < td && t.status === 'Open').length } };
}
/** d = {act:'add'|'done'|'undo'|'edit'|'move'|'del', id, task, date, time, pri, note, view} */
function otSave_(d, user) {
  otOwner_(user);
  const sh = xtab_(OT_TAB, OT_H); sh.getRange('C:C').setNumberFormat('@');
  const act = s_(d.act), td = ymd_(new Date());
  if (act === 'add') {
    const task = txt_(d.task, 500); if (!task) throw new Error('Type or say the task.');
    const date = /^\d{4}-\d{2}-\d{2}$/.test(d.date || '') ? d.date : hoNext_(td);
    sh.getRange(sh.getLastRow() + 1, 1, 1, OT_H.length).setValues([[Utilities.getUuid().slice(0, 12), date, hoHm_(d.time), task, d.pri ? 'High' : '', 'Open', '', txt_(d.note, 500), new Date(), '']]);
    sh.getRange('B:B').setNumberFormat('yyyy-mm-dd');
  } else {
    const rows = xrows_(OT_TAB, OT_H), i = rows.findIndex(r => s_(r[0]) === s_(d.id)); if (i < 0) throw new Error('Task not found – refresh.');
    const n = i + 2;
    if (act === 'done') sh.getRange(n, 6, 1, 2).setValues([['Done', new Date()]]);
    else if (act === 'undo') sh.getRange(n, 6, 1, 2).setValues([['Open', '']]);
    else if (act === 'del') sh.deleteRow(n);
    else if (act === 'move') {
      const to = /^\d{4}-\d{2}-\d{2}$/.test(d.date || '') ? d.date : td;
      sh.getRange(n, 2).setValue(to); sh.getRange(n, 10).setValue(s_(rows[i][9]) || ymd_(rows[i][1]));
    } else if (act === 'edit') {
      const task = txt_(d.task, 500); if (!task) throw new Error('The task cannot be empty.');
      sh.getRange(n, 3, 1, 3).setValues([[hoHm_(d.time), task, d.pri ? 'High' : '']]); sh.getRange(n, 8).setValue(txt_(d.note, 500));
    } else throw new Error('Unknown change.');
  }
  return otList_({ date: d.view }, user);
}
